diff --git a/src/duration.js b/src/duration.js
index 8bc22ec..0eea27c 100644
--- a/src/duration.js
+++ b/src/duration.js
@@ -17,3 +17,19 @@ export function formatDuration(seconds) {
   }
   return out;
 }
+
+/** Parse a compact duration such as "1h30m" back into whole seconds. */
+export function parseDuration(text) {
+  if (typeof text != "string" || text.length == 0) throw new RangeError("bad duration");
+  var total = 0, digits = "", seen = "";
+  for (var ch of text) {
+    if (ch >= "0" && ch <= "9") { digits += ch; continue; }
+    var size = ch == "h" ? 3600 : ch == "m" ? 60 : ch == "s" ? 1 : 0;
+    if (!size || digits == "" || seen.includes(ch)) throw new RangeError("bad duration");
+    total += Number(digits) * size;
+    digits = "";
+    seen += ch;
+  }
+  if (digits != "") throw new RangeError("bad duration");
+  return total;
+}
