index f9d8711..f8f045d 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,6 +1,11 @@
-export const DEFAULTS = { retries: 2, timeoutMs: 5000 };
+export const DEFAULTS = Object.freeze({ retries: 2, timeout: 5 });

-/** Merge user options over defaults. */
+/** Merge user options over defaults; a deprecated `timeoutMs` becomes `timeout` in seconds. */
 export function resolveOptions(options = {}) {
-  return { ...DEFAULTS, ...options };
+  const resolved = Object.assign({}, DEFAULTS);
+  for (const key of Object.keys(options)) {
+    if (key !== "timeoutMs") resolved[key] = options[key];
+  }
+  if ("timeoutMs" in options && !("timeout" in options)) resolved.timeout = options.timeoutMs / 1000;
+  return resolved;
 }
